using UnityEngine;
namespace MetaPort.Games.PuzzlingPlaces { public class PuzzlingManager : MonoBehaviour { public Transform[] pieces; void Awake(){ pieces=new Transform[12]; for(int i=0;i<12;i++){ var go=GameObject.CreatePrimitive(PrimitiveType.Cube); go.name=$"PuzzlePiece_{i}"; go.transform.SetParent(transform,false); go.transform.localPosition=new Vector3(Random.Range(-0.5f,0.5f), Random.Range(0.8f,1.2f), Random.Range(1.5f,2f)); go.transform.localScale=Vector3.one*0.15f; var mat=new Material(Shader.Find("MetaPort/SpatialWindow")); mat.SetColor("_BaseColor", Color.HSVToRGB(Random.value,0.5f,0.9f)); go.GetComponent<Renderer>().material=mat; pieces[i]=go.transform; go.AddComponent<Rigidbody>().useGravity=false; var ph=go.AddComponent<UI.SpatialUI.GrabHandle>(); var sw=go.AddComponent<UI.SpatialUI.SpatialWindow>(); } } } }
